SELECT id, account_id AS applicant_id, unit_id, start_date, end_date, end_date - start_date + 1 AS days, status
FROM leave_request
WHERE account_id = #{applicant} AND id > #{after}
ORDER BY id LIMIT #{limit}

SELECT id, account_id AS applicant_id, unit_id, start_date, end_date, end_date - start_date + 1 AS days, status
FROM leave_request
WHERE status = 'PENDING' AND id > #{filter.after}

    AND unit_id IN
    #{unit}

ORDER BY id LIMIT #{filter.limit}
